/**
 * Templates used to render buildings in the list.
 *
 * Building data is schema.org JSON-LD (an Article whose mainEntity is the
 * building), generated by _scripts/buildings.js. onloadPlaceData adds the
 * fields the core modules use (id, slug, title, lat, lng) and keeps
 * the JSON-LD for the building in the ld property.
 *
 * The following functions are defined in this file:
 *
 * - getPlaceHTML - assembles HTML for the list view (short) and returns a HTML Element
 * - getAdditionalInfo - assembles HTML for expanded view and returns an HTML String
 * - getInfoWindowContent - assembles HTML for the map infoWindow and returns an HTML String
 * - onloadPlaceData - called when the data is loaded, can be used to set up any additional data structures or intervals
 * - onrenderPlaceData - called when the data is rendered, can be used to set up any additional data structures or intervals
 * - onunloadPlaceData - called when the data is unloaded, can be used to clear any intervals or event listeners
 *
 * These are called using the module namespace object, which is added to the spacefinder.data object when this module is loaded.
 * i.e. spacefinder.data.buildings.getPlaceHTML( building ) will call the getPlaceHTML function in this module.
 */
import { spacefinder } from '../../js/modules/config.mjs';
import { splog, escapeHTML as esc, getDirectionsLink, createPlaceElement, getInfoWindowHTML } from '../../js/modules/utilities.mjs';
import { getPublishedEntities, getPropertyValue as propertyValue, getFeatureValue as featureValue, getFeatureKeys } from '../../js/modules/jsonld.mjs';

export const namespace = 'buildings';

/* Labels for the schema.org types used for buildings */
const TYPE_LABELS = {
    'CivicStructure': 'University building',
    'Accommodation': 'Accommodation',
    'LandmarksOrHistoricalBuildings': 'Historic building',
    'Place': 'Building'
};

/* Filter keys (from filters.json) for each amenityFeature */
const FILTER_KEYS = {
    'accommodation': 'category',
    'libraries': 'category',
    'culture': 'category',
    'sport': 'category',
    'wheelchair_entrance': 'accessibility',
    'accessable': 'accessibility',
    'entrances': 'accessibility'
};

const ENTRANCE_TYPE = 'https://wiki.openstreetmap.org/wiki/Key:entrance';

/**
 * Gets a single line address for a building
 * @param {Object} ld JSON-LD building
 * @return {String} HTML
 */
function getAddress( ld ) {
    let parts = [];
    if ( ld.address.streetAddress ) {
        parts.push( esc( ld.address.streetAddress ) );
    }
    if ( ld.address.postalCode ) {
        parts.push( esc( ld.address.postalCode ) );
    }
    return parts.join( ', ' );
}

/**
 * Describes the access at an entrance from its OSM tags
 * @param {Object} entrance JSON-LD place for the entrance
 * @return {Array} descriptions
 */
function getEntranceDetails( entrance ) {
    let details = [];
    let wheelchair = featureValue( entrance, 'wheelchair' );
    if ( wheelchair === 'yes' ) {
        details.push( 'Wheelchair accessible' );
    } else if ( wheelchair === 'limited' ) {
        details.push( 'Limited wheelchair access' );
    } else if ( wheelchair === 'no' ) {
        details.push( 'Not wheelchair accessible' );
    }
    let door = featureValue( entrance, 'automatic_door' );
    if ( door === 'button' ) {
        details.push( 'Automatic door (push button)' );
    } else if ( door && door !== 'no' ) {
        details.push( 'Automatic door' );
    }
    if ( featureValue( entrance, 'ramp' ) === 'yes' ) {
        details.push( 'Ramp' );
    }
    let steps = featureValue( entrance, 'step_count' );
    if ( steps !== undefined ) {
        details.push( steps == 0 ? 'Step free': steps + ( steps == 1 ? ' step': ' steps' ) );
    }
    if ( entrance.description ) {
        details.push( esc( entrance.description ) );
    }
    return details;
}

/**
 * Renders list view for a building
 * @param {Object} building
 * @return {Element} HTML element
 */
export function getPlaceHTML( building ) {
    splog( 'getPlaceHTML (buildings module)' );
    let ld = building.ld;
    let details = '';
    if ( ld.image ) {
        details += '<img src="' + ld.image.contentUrl + '" class="place-image" loading="lazy" alt="' + esc( ld.image.description ) + '">';
    }
    /* list what's in the building: search only looks at the summary, so this lets a search for a department find the building (and shows why it matched) */
    let contents = building.contents.map( p => esc( p.name ) );
    if ( contents.length ) {
        details += '<p class="description">Also here: ' + contents.join( ', ' ) + '</p>';
    }
    return createPlaceElement( building, {
        classList: getClassList( building ),
        typeLabel: TYPE_LABELS[ ld['@type'] ],
        typeClass: ld['@type'],
        address: getAddress( ld ),
        details: details
    } );
}

/**
 * Gets additional information about a building.
 * @param {Object} building building data
 * @return {String} HTML
 */
export function getAdditionalInfo( building ) {
    splog( 'getAdditionalInfo (buildings module)' );
    let ld = building.ld;
    let html = '<section class="section-facts"><h4>Key Facts</h4><ul class="bulleticons"><li class="icon-marker switch-view"><a class="show-map" href="#">Show on map</a></li>';
    let address = getAddress( ld );
    html += '<li class="icon-address">' + ( address ? address + ' (': '(' ) + getDirectionsLink( building.lat, building.lng ) + ')</li>';
    let levels = propertyValue( ld.additionalProperty, 'building:levels' );
    if ( levels ) {
        html += '<li class="icon-info-circled">' + levels + ( levels == 1 ? ' floor': ' floors' ) + '</li>';
    }
    let accessable = propertyValue( ld.additionalProperty, 'accessable' );
    if ( accessable ) {
        html += '<li class="icon-universal-access"><a target="placeurl" href="' + accessable + '">AccessAble access guide</a></li>';
    }
    if ( ld.url ) {
        html += '<li class="icon-link"><a target="placeurl" href="' + esc( ld.url ) + '">Website</a></li>';
    }
    let campusmap = ( ld.sameAs || [] ).find( url => url.indexOf( 'leeds.ac.uk/campusmap' ) !== -1 );
    if ( campusmap ) {
        html += '<li class="icon-link"><a target="placeurl" href="' + campusmap + '">University campus map</a></li>';
    }
    html += '</ul></section>';

    if ( ld.description ) {
        html += '<section class="section-about"><h4>About</h4><p>' + ld.description + '</p></section>';
    }

    if ( building.entrances.length ) {
        html += '<section class="section-entrances"><h4>Entrances</h4><ul class="bulleticons">';
        building.entrances.forEach( entrance => {
            let details = getEntranceDetails( entrance );
            let icon = featureValue( entrance, 'wheelchair' ) === 'yes' ? 'icon-disabled': 'icon-direction';
            html += '<li class="' + icon + '">' + esc( entrance.name );
            if ( details.length ) {
                html += ': ' + details.join( ', ' );
            }
            html += ' (' + getDirectionsLink( entrance.latitude, entrance.longitude ) + ')</li>';
        });
        html += '</ul></section>';
    }

    if ( building.contents.length ) {
        html += '<section class="section-contents"><h4>In this building</h4>';
        building.contents.forEach( place => {
            html += '<details><summary>' + esc( place.name ) + '</summary>';
            if ( place.description ) {
                html += '<p>' + place.description + '</p>';
            }
            if ( place.sameAs ) {
                html += '<p><a target="placeurl" href="' + place.sameAs + '">View on the University campus map</a></p>';
            }
            html += '</details>';
        });
        html += '</section>';
    }

    if ( ld.image ) {
        html += '<section class="section-credits"><h4>Photo</h4><p>' + esc( ld.image.creditText );
        html += ' (<a target="placeurl" href="' + ld.image.acquireLicensePage + '">details</a>)</p></section>';
    }
    html += '<section class="section-credits"><p>Building outline and entrances &copy; <a target="placeurl" href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a></p></section>';
    return html;
}

/**
 * Returns HTML for an individual building's infoWindow
 * @param {Object} building
 * @returns {String} HTML content for building infoWindow
 */
export function getInfoWindowContent( building ) {
    return getInfoWindowHTML( building.title, [ TYPE_LABELS[ building.ld['@type'] ], getAddress( building.ld ) ] );
}

/**
 * Gets a list of classes for a building container to facilitate filtering
 * @param {Object} building building data
 * @return {String} classList Space separated list of classnames
 */
function getClassList( building ) {
    let classList = 'place_type_' + building.ld['@type'].toLowerCase();
    getFeatureKeys( building.ld ).forEach( key => {
        if ( FILTER_KEYS[ key ] ) {
            classList += ' ' + FILTER_KEYS[ key ] + '_' + key;
        }
    });
    return classList;
}

/**
 * Function called when the data is loaded
 * Turns the JSON-LD into the place objects used by the core modules
 * @param {*} data - JSON-LD data for the buildings
 */
export function onloadPlaceData( data ) {
    splog( 'onloadPlaceData (buildings module)' );
    spacefinder.data[namespace].places = getPublishedEntities( data ).map( ld => {
        let contained = ld.containsPlace || [];
        return {
            id: propertyValue( ld.identifier, 'osm' ).replace( '/', '-' ),
            slug: propertyValue( ld.identifier, 'slug' ),
            title: ld.name,
            lat: ld.latitude,
            lng: ld.longitude,
            entrances: contained.filter( p => p.additionalType === ENTRANCE_TYPE ),
            contents: contained.filter( p => p.additionalType !== ENTRANCE_TYPE ),
            ld: ld
        };
    });
}

/**
 * Function called after the data is rendered
 */
export function onrenderPlaceData() {
    splog( 'onrenderPlaceData (buildings module)' );
}

/**
 * Function called when the data is unloaded
 */
export function onunloadPlaceData() {
    splog( 'onunloadPlaceData (buildings module)' );
}
